using System;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalRoadGlyphFix{
static FinalRoadGlyphFix(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalRoadGlyphFix.request")||EditorApplication.isCompiling)return;File.Delete("FinalRoadGlyphFix.request");Run();}
static T F<T>(object o,string n)=>(T)o.GetType().GetField(n).GetValue(o);
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");string backup="FinalEnvironmentRoadBackup/RoadGlyphFix-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);int cycles=0,arrows=0;var seen=new HashSet<Mesh>();MeshFilter preview=null;
foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){var r=f.GetComponent<MeshRenderer>();if(!r||!r.sharedMaterial||r.sharedMaterial.name!="City PNG Markings"||!seen.Add(f.sharedMesh))continue;
var d=typeof(FinalCitywideStops).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f});var mark=F<Vector4[]>(d,"mark");int tile=F<int>(d,"tile");if(mark==null||!(tile==0||tile==3||tile==4||tile==5))continue;float len=Mathf.Max(r.bounds.size.x,r.bounds.size.z);if(len<55)continue;var m=f.sharedMesh;string path=AssetDatabase.GetAssetPath(m);if(!path.StartsWith("Assets/Scenes/Oasis/FinalEnvironmentRoads/"))throw new Exception("Unexpected asset "+path);File.Copy(path,backup+"/"+Path.GetFileName(path));float old=mark[0].w;float repeats=Mathf.Max(1,len/32);float pivot=(mark.Min(v=>v.y)+mark.Max(v=>v.y))*.5f;for(int i=0;i<mark.Length;i++){if(tile==3)mark[i].x-=3*32;mark[i].y=(mark[i].y-pivot)*repeats/old+repeats*.5f;mark[i].w=repeats;}m.SetUVs(3,mark.ToList());EditorUtility.SetDirty(m);if(tile==3){cycles++;preview=f;}arrows++;log.AppendLine(f.name+" tile="+tile+" -> "+(tile==3?0:tile)+" repeat length=32m");}
AssetDatabase.SaveAssets();if(preview){var p=preview.GetComponent<Renderer>().bounds.center;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,p+Vector3.up*65,p,"Road-Glyph-Fixed"});}
var shader=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Markings.mat").shader;int errors=ShaderUtil.GetShaderMessages(shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);log.AppendLine("SUCCESS bicycle road layouts replaced="+cycles+"; arrow layouts corrected="+arrows+"; shader errors=0; geometry and base texture UVs unchanged; backup="+backup);
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/RoadGlyphFixReport.txt",log.ToString());}}